1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_MULTIPLIER = 1.10;
11	
12	const BASE_PREMIUM: Record<string, number> = {
13	  sword: 100,
14	  amulet: 60,
15	  staff: 80,
16	  potion: 40,
17	};
18	
19	const roundUp = (n: number): number => Math.ceil(n - 1e-9);
20	
21	const basePremiumOf = (item: Item): number => BASE_PREMIUM[item.type];
22	
23	const sumBasePremiums = (items: Item[]): number =>
24	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
25	
26	const computeQuotePremium = (items: Item[]): number =>
27	  roundUp(sumBasePremiums(items) * FIRST_INSURANCE_MULTIPLIER + PROCESSING_FEE);
28	
29	export const runScenario = (scenario: Scenario): ScenarioResult => ({
30	  results: scenario.steps.map((step) => ({ premium: computeQuotePremium(step.items) })),
31	});
